<script setup lang="ts">
import { onMounted, ref } from "vue";
import { Eye, LoaderCircle, X } from "lucide-vue-next";
import DataPanel from "@/components/operations/DataPanel.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiContactRecord } from "@/data/models/operations";

const loading = ref(true); const saving = ref(false); const error = ref(""); const status = ref(""); const messages = ref<UiContactRecord[]>([]); const selected = ref<UiContactRecord | null>(null);
async function load() { loading.value = true; error.value = ""; try { messages.value = (await operationsRepository.contactMessages({ status: status.value, per_page: 100 })).items; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load messages."; } finally { loading.value = false; } }
async function setStatus(value: string) { if (!selected.value) return; saving.value = true; try { await operationsRepository.updateContactStatus(selected.value.id, value); selected.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to update message."; } finally { saving.value = false; } }
onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-violet">Customer operations</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Support inbox</h2><p class="mt-1 text-[13px] text-ink3">Contact and support requests submitted from the application.</p></div><label class="text-[11px] font-semibold">Status<select v-model="status" class="ops-input min-w-40" @change="load"><option value="">All statuses</option><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="closed">Closed</option></select></label></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><DataPanel title="Messages" :description="`${messages.length} requests`" :loading="loading" :empty="!messages.length"><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Sender</th><th class="px-4 py-3">Subject</th><th class="px-4 py-3">Type</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">View</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in messages" :key="item.id"><td class="px-5 py-3.5"><p class="font-semibold">{{ item.name }}</p><p class="text-ink3">{{ item.email }}</p></td><td class="px-4 py-3.5"><p class="font-semibold">{{ item.subject }}</p><p class="text-[10px] text-ink3">{{ item.createdAt ? new Date(item.createdAt).toLocaleString() : '' }}</p></td><td class="px-4 py-3.5 capitalize">{{ item.kind }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td><td class="px-5 py-3.5 text-right"><button class="ops-icon-button" @click="selected = item"><Eye :size="14" /></button></td></tr></tbody></table></div></DataPanel><div v-if="selected" class="ops-legacy-modal fixed inset-0 z-50 grid place-items-center bg-black/35 p-4" @click.self="selected = null"><div class="w-full max-w-2xl rounded-2xl bg-bg-card p-5 shadow-xl"><div class="flex items-start justify-between"><div><h3 class="text-[17px] font-bold">{{ selected.subject }}</h3><p class="mt-1 text-[12px] text-ink3">{{ selected.name }} · {{ selected.email }}</p></div><button @click="selected = null"><X :size="18" /></button></div><p class="mt-5 whitespace-pre-wrap rounded-xl bg-bg-soft p-4 text-[13px] leading-6 text-ink2">{{ selected.message }}</p><div class="mt-5 flex flex-wrap justify-end gap-2"><button v-for="value in ['open', 'in_progress', 'resolved', 'closed']" :key="value" class="ops-button-secondary capitalize" :disabled="saving || selected.status === value" @click="setStatus(value)"><LoaderCircle v-if="saving" :size="13" class="mr-1 inline animate-spin" />{{ value.replace('_', ' ') }}</button></div></div></div></div></template>
